{"packet_id":"D067-01","doc_id":"D067","jurisdiction":"NJ","category":"security_deposits","lifecycle":"enacted","title":"New Jersey Security Deposit Law","requirement":"A landlord may not collect a security deposit above one and one-half times one month's rent plus the first month's rent, may not raise the deposit more than 10% a year, and must return deposit plus interest within 30 days of termination.","key_value":"1.5 months' rent; deposit increase max 10% per year","coverage_conditions":"Residential rentals in New Jersey; the deposit provisions do not apply to security deposits for seasonal use or rental of not more than 125 consecutive days.","applicability":{"conditions":[],"per_tenancy":"Residential tenancy; excludes seasonal use or rental of not more than 125 consecutive days.","coverage_quotes":[]},"exemptions":"Security deposits for seasonal use or rental (term of not more than 125 consecutive days); a landlord is not required to collect a security deposit at all.","penalty":"Tenant may sue for double the amount of the security deposit wrongfully withheld, plus court costs and reasonable attorney's fees.","effective_date":null,"valid_through":null,"citation":"N.J.S.A. 46:8-21.2","quoted_span":"The maximum-security deposit to be collected by the landlord cannot be more than one and one-half times one month's rent (N.J.S.A. 46:8-21.2). It can be less.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D067-01","doc_id":"D067","jurisdiction":"NJ","category":"security_deposits","lifecycle":"enacted","title":"Safe Housing Act security deposit return after domestic violence lease termination","requirement":"When a tenant ends a lease under the Safe Housing Act, the landlord must make the deposit plus interest available within 15 business days and notify the tenant within three business days where to collect it.","key_value":"15 business days","coverage_conditions":"Tenancies terminated by domestic violence victims under the Safe Housing Act; the law does not apply to transient or seasonal rentals.","applicability":{"conditions":[],"per_tenancy":"Lease terminated by a victim of domestic violence under the Safe Housing Act (N.J.S.A. 46:8-9.4 et seq.).","coverage_quotes":[]},"exemptions":"Transient or seasonal rentals.","penalty":null,"effective_date":null,"valid_through":null,"citation":"N.J.S.A. 46:8-9.6","quoted_span":"Within 15 business days after the lease is terminated, the landlord shall make available the return of the tenant's security deposit, plus any interest earned, to the tenant or the tenant's agent.","interaction":null,"relations":[],"confidence":0.75,"conflict_flag":false,"conflict_note":null}
